import{_ as t,c as n,a2 as s,o as e}from"./chunks/framework.BnrAgU0Y.js";const l="/bllm/assets/c560989e4b7ef9ed590fd9552138ace5.aXOQ6Vu0.png",u=JSON.parse('{"title":"Math agent","description":"Math agent","frontmatter":{"title":"Math agent","description":"Math agent","layout":"doc"},"headers":[],"relativePath":"langflow/tutorials-math-agent.md","filePath":"langflow/tutorials-math-agent.md"}'),o={name:"langflow/tutorials-math-agent.md"};function i(r,a,p,g,h,c){return e(),n("div",null,a[0]||(a[0]=[s('<h1 id="math-agent" tabindex="-1">Math agent <a class="header-anchor" href="#math-agent" aria-label="Permalink to &quot;Math agent&quot;">​</a></h1><p>构建一个 <strong>Math Agent</strong>（数学代理）流程，用于一个具有代理功能的应用，使用 <strong>Tool-calling agent</strong>（工具调用代理）组件。</p><p>在此流程中，<strong>Tool-calling agent</strong> 使用 <strong>Open AI</strong> 的 LLM（大语言模型）来推理解决数学问题。 它选择 <strong>Calculator</strong>（计算器）工具来处理简单的数学问题，而对于更复杂的问题则使用 <strong>Python REPL</strong> 工具（结合 Python 的 <code>math</code> 库）。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>要使用此流程，您需要一个 OpenAI API 密钥。</p><h2 id="打开-langflow-并开始一个新流程" tabindex="-1">打开 Langflow 并开始一个新流程 <a class="header-anchor" href="#打开-langflow-并开始一个新流程" aria-label="Permalink to &quot;打开 Langflow 并开始一个新流程&quot;">​</a></h2><p>点击 <strong>New Flow</strong>，然后选择 <strong>Math Agent</strong> 流程。</p><p>这将打开一个初始流程，包含使用 Tool-calling agent（工具调用代理）运行代理应用程序所需的组件。</p><h2 id="math-agent-流程" tabindex="-1">Math Agent 流程 <a class="header-anchor" href="#math-agent-流程" aria-label="Permalink to &quot;Math Agent 流程&quot;">​</a></h2><p><img src="'+l+`" alt=""></p><p><strong>Math Agent</strong> 流程由以下组件组成：</p><ul><li><strong>工具调用代理</strong> 组件使用连接的LLM（大语言模型）来推理用户的输入，并在连接的工具中进行选择以完成其任务。</li><li><strong>Python REPL工具</strong> 组件在REPL（Read-Evaluate-Print Loop，即读取-求值-输出循环）解释器中执行Python代码。</li><li><strong>计算器</strong> 组件执行基本的算术运算。</li><li><strong>聊天输入</strong> 组件接受用户输入到聊天中。</li><li><strong>提示</strong> 组件将用户输入与用户定义的提示相结合。</li><li><strong>聊天输出</strong> 组件将流程的输出打印到聊天中。</li><li><strong>OpenAI</strong> 模型组件将用户输入和提示发送至OpenAI API并接收响应。</li></ul><h2 id="运行数学代理流程" tabindex="-1">运行数学代理流程 <a class="header-anchor" href="#运行数学代理流程" aria-label="Permalink to &quot;运行数学代理流程&quot;">​</a></h2><ol><li><p>在 Open AI 组件中添加您的凭据。</p></li><li><p>点击 <strong>Playground</strong> 开始一个聊天会话。</p></li><li><p>输入一个简单的数学问题，例如 <code>2 + 2</code>，然后确保机器人能给出正确答案。</p></li><li><p>为了确认 REPL（Read-Eval-Print Loop）解释器正常工作，直接用 <code>math</code> 库进行测试，比如输入 <code>math.sqrt(4)</code>，看看机器人是否回应 <code>4</code>。</p></li><li><p>代理也能解决更复杂的文字题。例如，可以向代理提出以下数学问题：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The equation 24x2+25x−47ax−2=−8x−3−53ax−2 is true for all values of x≠2a, where a is a constant.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># What is the value of a?</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A) -16</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># B) -3</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># C) 3</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># D) 16</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>代理应该回应 <code>B</code>。</p></li></ol><p>现在您的查询已经从 <strong>Chat input</strong> 到 <strong>Chat output</strong> 完成了整个旅程，您已完成 <strong>Math Agent</strong> 流程。</p>`,15)]))}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
